const tableColumns = `-- name: TableColumns :many
SELECT a.oid, a.class_oid, a.name, t.name AS type_name, a.type_oid, a.not_null,
       a.decl_type, a.type_length, a.type_scale,
       a.auto_increment, a.is_primary_key, a.is_unique
FROM sql_attribute a
JOIN sql_class c ON c.oid = a.class_oid
JOIN sql_type t ON t.oid = a.type_oid
WHERE c.name = ?
ORDER BY a.num
`

type TableColumnsRow struct {
	Oid           int64
	ClassOid      int64
	Name          string
	TypeName      string
	TypeOid       int64
	NotNull       int64
	DeclType      string
	TypeLength    int64
	TypeScale     int64
	AutoIncrement int64
	IsPrimaryKey  int64
	IsUnique      int64
}

func (q *Queries) TableColumns(ctx context.Context, name string) ([]TableColumnsRow, error) {
	rows, err := q.db.QueryContext(ctx, tableColumns, name)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []TableColumnsRow
	for rows.Next() {
		var i TableColumnsRow
		if err := rows.Scan(
			&i.Oid,
			&i.ClassOid,
			&i.Name,
			&i.TypeName,
			&i.TypeOid,
			&i.NotNull,
			&i.DeclType,
			&i.TypeLength,
			&i.TypeScale,
			&i.AutoIncrement,
			&i.IsPrimaryKey,
			&i.IsUnique,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

